/// Test-only ownership of an ordinary child, with no Android resources.
///
/// The caller must stop and join this child. The fixture has created no
/// namespace, network, or runtime directory for cleanup to mutate.
#[cfg(test)]
pub(crate) fn owned_process_for_lifecycle_test(spec: CellSpec, child: Child) -> Self {
    Self {
        spec,
        child,
        network: None,
        cleaned: true,
    }
}
